  const subtleText = isDark ? UX4GColors.neutral300 : UX4GColors.neutral600;

  const stateOptions = [
    { id: 'dl', label: 'Delhi' },
    { id: 'mh', label: 'Maharashtra' },
    { id: 'up', label: 'Uttar Pradesh' },
    { id: 'ka', label: 'Karnataka' },
    { id: 'tn', label: 'Tamil Nadu' },
  ];

