import {
  SafeAreaView,
  ScrollView,
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
} from 'react-native';
import {
  Ux4gAppHeader,
  Ux4gButton,
  Ux4gButtonVariant,
  Ux4gButtonSize,
  Ux4gSelectionDropdown,
  Ux4gFileUpload,
  Ux4gDivider,
  Ux4gDividerOrientation,
  Ux4gIcon,
  UX4GColors,
} from 'ux4g-react-native-components';

export const InlineFeedbackGuidanceCardScreen = ({ isDark = false }: { isDark?: boolean }) => {
  const [selectedCategory, setSelectedCategory] = useState<string[]>(['sc']);

  const primaryColor = isDark ? UX4GColors.primary300 : '#432CBB';
  const titleColor = isDark ? UX4GColors.neutral50 : '#111827';
  const subtleColor = isDark ? UX4GColors.neutral200 : '#4B5563';
  const screenBg = isDark ? UX4GColors.primary800 : '#F2EFFF';
  const cardBg = isDark ? UX4GColors.neutral800 : '#FFFFFF';

  const warningBg = isDark ? 'rgba(250, 140, 22, 0.15)' : UX4GColors.orange50;
  const warningBorder = isDark ? UX4GColors.orange700 : UX4GColors.orange300;
  const warningTextColor = isDark ? UX4GColors.orange300 : UX4GColors.orange800;
  const warningIconColor = isDark ? UX4GColors.orange400 : UX4GColors.orange600;

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: screenBg }]}>
      {/* App Header with logos and elevation */}
      <Ux4gAppHeader
        elevation={2}
        variant="light"
        title=""
        leadingSpacing={8}
        leadingWidgets={[
          <NationalEmblemLogo key="emblem" isDark={isDark} height={40} />,
          <View key="divider" style={styles.headerDividerWrapper}>
            <Ux4gDivider
              orientation={Ux4gDividerOrientation.vertical}
              color="#D1D5DB"
            />
          </View>,
          <UnionLogo
            key="union"
            height={32}
            color={isDark ? UX4GColors.primary300 : UX4GColors.primary600}
          />,
        ]}
      actions={[
        {
          customWidget: (
            <TouchableOpacity
              key="menu"
              style={styles.menuBtn}
              onPress={() => {}}
            >
              <Text style={styles.menuIcon}>☰</Text>
            </TouchableOpacity>
          ),
        },
      ]}
      />

      <ScrollView style={styles.scroll} contentContainerStyle={styles.content}>
        {/* Card container */}
        <View style={[styles.card, { backgroundColor: cardBg }]}>
          {/* Back button */}
          <View style={styles.backWrapper}>
            <Ux4gButton
              text="Back"
              onPress={() => {}}
              variant={Ux4gButtonVariant.ghost}
              leadingIcon="arrow_back"
              contentColor={primaryColor}
              size={Ux4gButtonSize.small}
            />
          </View>

          {/* Title */}
          <Text style={[styles.title, { color: titleColor }]}>
            Conditional Guidance
          </Text>

          {/* Description */}
          <Text style={[styles.description, { color: subtleColor }]}>
            Context-sensitive info appears based on the selected field value.
          </Text>

          {/* Selection Dropdown */}
          <Ux4gSelectionDropdown
            label="Social Category"
            description="Select your reservation category"
            placeholder="Please select.."
            options={[
              { id: 'sc', label: 'Scheduled Caste (SC)' },
              { id: 'st', label: 'Scheduled Tribe (ST)' },
              { id: 'obc', label: 'OBC' },
              { id: 'general', label: 'General' },
            ]}
            selectedOptionIds={selectedCategory}
            onSelectionChange={setSelectedCategory}
            mode="single"
          />

          <View style={styles.spacing} />

          {/* File upload area */}
          <Ux4gFileUpload
            maxFiles={1}
            maxFileSize={5 * 1024 * 1024}
            allowedExtensions={['pdf', 'jpg', 'png']}
            borderStyle="dashed"
            onFilesChanged={() => {}}
          />

          <View style={styles.spacing} />

          {/* Conditional Warning Banner */}
          {selectedCategory.includes('sc') && (
            <View
              style={[
                styles.warningBanner,
                { backgroundColor: warningBg, borderColor: warningBorder },
              ]}
            >
              <Ux4gIcon name="error" size={18} color={warningIconColor} />
              <View style={styles.warningTextContainer}>
                <Text style={[styles.warningTitle, { color: warningTextColor }]}>
                  Additional Document Required
                </Text>
                <Text style={[styles.warningBody, { color: warningTextColor }]}>
                  Since you selected SC category, please upload your caste certificate in the Documents step.
                </Text>
              </View>
            </View>
          )}
        </View>
      </ScrollView>

      {/* Continue button at bottom */}
      <View style={styles.bottomBar}>
        <Ux4gButton
          text="Continue"
          onPress={() => {}}
          variant={Ux4gButtonVariant.primary}
          size={Ux4gButtonSize.large}
          height={48}
          backgroundColor={isDark ? UX4GColors.primary300 : '#4A2BC2'}
          contentColor={isDark ? '#000000' : '#FFFFFF'}
          borderRadius={8}
        />
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  menuBtn: {
    width: 36,
    height: 36,
    borderRadius: 8,
    borderWidth: 1.5,
    borderColor: UX4GColors.primary200,
    backgroundColor: UX4GColors.neutral0,
    justifyContent: 'center',
    alignItems: 'center',
  },
  menuIcon: {
    fontSize: 18,
    color: UX4GColors.primary,
  },
  safeArea: {
    flex: 1,
  },
  headerDividerWrapper: {
    height: 32,
    justifyContent: 'center',
  },
  scroll: {
    flex: 1,
  },
  content: {
    padding: 16,
  },
  card: {
    width: '100%',
    padding: 16,
    borderRadius: 16,
  },
  backWrapper: {
    alignSelf: 'flex-start',
    marginBottom: 20,
  },
  title: {
    fontSize: 18,
    fontWeight: '800',
    marginBottom: 8,
  },
  description: {
    fontSize: 13,
    lineHeight: 18,
    marginBottom: 20,
  },
  spacing: {
    height: 20,
  },
  warningBanner: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    padding: 12,
    borderRadius: 8,
    borderWidth: 1,
    gap: 8,
  },
  warningTextContainer: {
    flex: 1,
  },
  warningTitle: {
    fontSize: 13,
    fontWeight: '700',
    marginBottom: 4,
  },
  warningBody: {
    fontSize: 13,
    lineHeight: 18,
  },
  bottomBar: {
    padding: 16,
    paddingTop: 0,
  },
});
