import {
  SafeAreaView,
  ScrollView,
  View,
  Text,
  Image,
  StyleSheet,
} from 'react-native';
import {
  Ux4gAppHeader,
  Ux4gCard,
  Ux4gInputField,
  Ux4gTextArea,
  Ux4gSelectionDropdown,
  Ux4gButton,
  Ux4gButtonVariant,
  Ux4gButtonSize,
  Ux4gDivider,
  Ux4gDividerOrientation,
  UX4GColors,
} from 'ux4g-react-native-components';

const CATEGORIES = [
  { label: 'Technical Issue', value: 'tech' },
  { label: 'Payment Problem', value: 'payment' },
  { label: 'Document Verification', value: 'doc' },
  { label: 'Account Access', value: 'account' },
  { label: 'Service Delay', value: 'delay' },
  { label: 'Other', value: 'other' },
];

/// Card Style variant — file complaint form inside a white card on purple background.
export const FileComplaintCardScreen = ({ isDark = false }: { isDark?: boolean }) => {
  const [subject, setSubject] = useState('');
  const [category, setCategory] = useState('');
  const [description, setDescription] = useState('');

  const screenBg = isDark ? UX4GColors.primary800 : UX4GColors.primary100;
  const cardBg = isDark ? '#1A1A1A' : '#FFFFFF';
  const titleColor = isDark ? '#FFFFFF' : '#111827';
  const subtleTextColor = isDark ? '#9CA3AF' : '#4B5563';
  const labelColor = isDark ? '#FFFFFF' : '#111827';

  return (
    <SafeAreaView style={[styles.safeArea, { backgroundColor: screenBg }]}>
      {/* App Header */}
      <Ux4gAppHeader
        elevation={2}
        variant="light"
        title=""
        leadingSpacing={8}
        leadingWidgets={[
          <NationalEmblemLogo key="emblem" isDark={isDark} height={40} />,
          <View key="divider" style={styles.headerDividerWrapper}>
            <Ux4gDivider
              orientation={Ux4gDividerOrientation.vertical}
              color="#D1D5DB"
            />
          </View>,
          <UnionLogo
            key="union"
            size={32}
            color={isDark ? UX4GColors.primary300 : UX4GColors.primary600}
          />,
        ]}
      actions={[
        {
          customWidget: (
            <TouchableOpacity
              key="menu"
              style={styles.menuBtn}
              onPress={() => {}}
            >
              <Text style={styles.menuIcon}>☰</Text>
            </TouchableOpacity>
          ),
        },
      ]}
      />

      {/* White Card Content */}
      <ScrollView
        style={styles.scroll}
        contentContainerStyle={styles.scrollContent}
      >
        <Ux4gCard
          backgroundColor={cardBg}
          cornerRadius={16}
          style={styles.card}
        >
          <Text style={[styles.title, { color: titleColor }]}>
            File a complaint
          </Text>
          <Text style={[styles.subtitle, { color: subtleTextColor }]}>
            Report a portal issue — we will respond within 2 working days.
          </Text>

          {/* Subject */}
          <Text style={[styles.label, { color: labelColor }]}>Subject</Text>
          <Ux4gInputField
            value={subject}
            onValueChange={setSubject}
            placeholder="Briefly describe the issue"
          />

          {/* Category */}
          <Text style={[styles.label, { color: labelColor, marginTop: 20 }]}>
            Category
          </Text>
          <Ux4gSelectionDropdown
            value={category}
            onSelect={setCategory}
            options={CATEGORIES}
            placeholder="Select Category"
          />

          {/* Description */}
          <Text style={[styles.label, { color: labelColor, marginTop: 20 }]}>
            Description
          </Text>
          <Ux4gTextArea
            value={description}
            onChangeText={setDescription}
            placeholder="Tell us what happened, when, and what you expect"
            rows={4}
          />

          {/* Action Buttons inside Card */}
          <View style={styles.cardButtonsContainer}>
            <Ux4gButton
              onPress={() => console.log('Submit complaint:', { subject, category, description })}
              text="Submit complaint"
              variant={Ux4gButtonVariant.primary}
              size={Ux4gButtonSize.large}
              height={48}
              backgroundColor={
                isDark ? UX4GColors.primary300 : UX4GColors.primary600
              }
              contentColor={isDark ? '#000000' : '#FFFFFF'}
            />
            <View style={{ height: 12 }} />
            <Ux4gButton
              onPress={() => console.log('Cancel')}
              text="Cancel"
              variant={Ux4gButtonVariant.outline}
              size={Ux4gButtonSize.large}
              height={48}
              borderColor={
                isDark ? UX4GColors.primary300 : UX4GColors.primary600
              }
              contentColor={
                isDark ? UX4GColors.primary300 : UX4GColors.primary600
              }
            />
          </View>
        </Ux4gCard>
      </ScrollView>

      {/* Powered by Digital India */}
      <View style={styles.footerRow}>
        <Text
          style={[
            styles.footerText,
            { color: isDark ? UX4GColors.neutral400 : '#6B7280' },
          ]}
        >
          Powered by -
        </Text>
        <Image
          source={{ uri: '/digital_india_logo.png' }}
          style={styles.digitalIndiaLogo}
          resizeMode="contain"
        />
      </View>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  menuBtn: {
    width: 36,
    height: 36,
    borderRadius: 8,
    borderWidth: 1.5,
    borderColor: UX4GColors.primary200,
    backgroundColor: UX4GColors.neutral0,
    justifyContent: 'center',
    alignItems: 'center',
  },
  menuIcon: {
    fontSize: 18,
    color: UX4GColors.primary,
  },
  safeArea: {
    flex: 1,
  },
  headerDividerWrapper: {
    height: 32,
    justifyContent: 'center',
  },
  scroll: {
    flex: 1,
  },
  scrollContent: {
    padding: 16,
  },
  card: {
    padding: 16,
    borderRadius: 16,
  },
  title: {
    fontSize: 22,
    fontWeight: '800',
    marginBottom: 8,
  },
  subtitle: {
    fontSize: 14,
    marginBottom: 24,
    lineHeight: 20,
  },
  label: {
    fontSize: 13,
    fontWeight: '600',
    marginBottom: 6,
  },
  cardButtonsContainer: {
    width: '100%',
    marginTop: 24,
  },
  footerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 4,
    paddingBottom: 12,
  },
  footerText: {
    fontSize: 11,
  },
  digitalIndiaLogo: {
    height: 20,
    width: 60,
  },
});
